// Port of hardware/display.py's render(): the browser preview draws the exact 128x64 frame the
// glasses receive. frontend/src/lib/oled.test.ts compares against frames generated by Python.
import assets from "../../../hardware/oled-assets.json";

export const WIDTH = 128;
export const HEIGHT = 64;
export interface Cue {
  icon_id: string | null;
  label: string;
  effective_tier: number;
  remaining_ms: number;
  direction?: string | null;
}
const font: Record<string, string[]> = Object.fromEntries(
  Object.entries(assets.glyphs).map(([char, rows]) => [char, rows.split(" ")]),
);
const bitmaps = assets.bitmaps as Record<string, string[]>;
const ICON_SIZE = 32;
const ICON_X = (WIDTH - ICON_SIZE) / 2;
const ICON_Y = 7;
const LABEL_Y = 46;

export class Bitmap {
  buffer = new Uint8Array((WIDTH * HEIGHT) / 8);
  pixel(x: number, y: number, value = 1) {
    if (x < 0 || x >= WIDTH || y < 0 || y >= HEIGHT) return;
    const index = y * (WIDTH / 8) + (x >> 3);
    const bit = 1 << (7 - (x % 8));
    if (value) this.buffer[index] |= bit;
    else this.buffer[index] &= 255 ^ bit;
  }
  get(x: number, y: number) {
    return (this.buffer[y * (WIDTH / 8) + (x >> 3)] >> (7 - (x % 8))) & 1;
  }
  line(x0: number, y0: number, x1: number, y1: number, value = 1) {
    const dx = Math.abs(x1 - x0);
    const sx = x0 < x1 ? 1 : -1;
    const dy = -Math.abs(y1 - y0);
    const sy = y0 < y1 ? 1 : -1;
    let error = dx + dy;
    for (;;) {
      this.pixel(x0, y0, value);
      if (x0 === x1 && y0 === y1) return;
      const twice = 2 * error;
      if (twice >= dy) {
        error += dy;
        x0 += sx;
      }
      if (twice <= dx) {
        error += dx;
        y0 += sy;
      }
    }
  }
  rect(x: number, y: number, width: number, height: number, fill = false) {
    if (fill) {
      for (let row = y; row < y + height; row++) this.line(x, row, x + width - 1, row);
      return;
    }
    this.line(x, y, x + width - 1, y);
    this.line(x, y + height - 1, x + width - 1, y + height - 1);
    this.line(x, y, x, y + height - 1);
    this.line(x + width - 1, y, x + width - 1, y + height - 1);
  }
  text(text: string, x: number, y: number, value = 1) {
    for (const char of text.toUpperCase()) {
      (font[char] ?? font["?"]).forEach((pixels, row) => {
        [...pixels].forEach((pixel, column) => {
          if (pixel === "1") this.pixel(x + column, y + row, value);
        });
      });
      x += 6;
    }
  }
  centered(text: string, y: number, value = 1) {
    this.text(text, Math.floor((WIDTH - (text.length * 6 - 1)) / 2), y, value);
  }
}

function drawIcon(bitmap: Bitmap, id: string) {
  (bitmaps[id] ?? []).forEach((bits, row) => {
    for (let column = 0; column < bits.length; column++)
      if (bits[column] === "1") bitmap.pixel(ICON_X + column, ICON_Y + row);
  });
}

export function fitLabel(label: string, width = 18) {
  const text = label.toUpperCase().split(/\s+/).filter(Boolean).join(" ");
  return text.length <= width ? text : text.slice(0, width - 3).trimEnd() + "...";
}

// A solid arrow beside the icon, on the side nearest the sound.
function drawDirection(bitmap: Bitmap, direction?: string | null) {
  if (direction !== "left" && direction !== "right") return;
  const middle = ICON_Y + ICON_SIZE / 2;
  for (let k = -6; k <= 6; k++)
    for (let x = 6 + Math.abs(k); x < 13; x++) bitmap.pixel(direction === "left" ? x : WIDTH - 1 - x, middle + k);
}

// One fixed layout for every tier; tier only changes the frame (see hardware/display.py render()).
export function render(cue: Cue | null, showLabels = true): Bitmap {
  const bitmap = new Bitmap();
  if (!cue || cue.effective_tier === 0 || cue.remaining_ms === 0 || !cue.icon_id) return bitmap;
  const tier = cue.effective_tier;
  if (tier >= 2) bitmap.rect(1, 1, 126, 62);
  if (tier >= 3) bitmap.rect(3, 3, 122, 58);
  drawIcon(bitmap, cue.icon_id);
  if (showLabels || tier === 4) {
    const text = fitLabel(cue.label);
    if (tier === 4) {
      bitmap.rect(6, LABEL_Y - 3, 116, 13, true);
      bitmap.centered(text, LABEL_Y, 0);
    } else bitmap.centered(text, LABEL_Y);
  }
  drawDirection(bitmap, cue.direction);
  return bitmap;
}

export const hex = (bitmap: Bitmap) =>
  Array.from(bitmap.buffer, (b) => b.toString(16).padStart(2, "0")).join(""); // taste-skill-ignore: hex bytes
